export function makeHostFollow(cfg) {
  // 状态放在插件实例内，避免上一次会话的模型残留到本次会话
  let currentModel = null
  return {
    // n 是当前会话的归一化请求（宿主 0.9 起模型只在这里）；
    // options.model 仅旧宿主（0.8）才会传，作为回退。
    observe(options, n) {
      const model = (n && n.model) || (options && options.model)
      if (model) currentModel = model
    },
    callConfig(options) { return { ...cfg, model: currentModel || cfg.model } },
  }
}"}
